(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.24)*18 + Math.sin(x*0.016+t*0.32)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8 + Math.cos((x-y)*0.012-t*0.18)*6;
  const w2y = Math.cos((x-y)*0.01-t*0.17)*8 + Math.sin((x+y)*0.011+t*0.2)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*70, 0.085, 1.8]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2 = Math.sqrt((sx-sY)**2+(sy-sX)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2 += Math.sin(d2*f*0.9-t*sp*0.8+0.7);
    iS2 += Math.cos(d2*f*0.6+t*sp*0.5+2.1);
  }
  const act=(aS+aS2)/16, inh=(iS+iS2)/16;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=(Math.sin(dist*0.03-ang*2+t*0.8)+Math.cos(dist*0.035+ang*5-t*0.9))*0.25;
  const warp = Math.sin(act*3.0)*Math.cos(inh*2.5)*0.5;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+spiral2+warp)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const vein = Math.abs(Math.sin(sx*0.08+t*0.3)*Math.cos(sy*0.06-t*0.25))<0.08?0.15:0;
  const micro = (Math.sin(sx*0.3+act*4)*Math.sin(sy*0.3+inh*3))*0.1;
  const blend = reaction*0.6+cell*0.2+vein+micro*0.1;
  const v = Math.tanh(blend*1.8)*0.5+0.5;
  const pal = [[5,10,45],[10,35,85],[15,75,115],[20,135,130],[45,175,140],[180,195,80],[220,160,55],[215,100,60],[175,50,70],[100,25,65],[40,12,55],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(spiral2)*0.1;
  const edge=Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.05:1.0;
  const shimmer=Math.sin(t*3+sx*0.05+sy*0.04)*0.03+1;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*shimmer)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*shimmer)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*shimmer)|0
  ];
}
